using Shop;

public class PriceCalculatorTests
{
    private static Order OrderOf(CustomerType customer) =>
        new(customer, [new OrderLine("A", 100m, 2), new OrderLine("B", 50m, 1)]);

    private static Order OrderWithSubtotal(CustomerType customer, decimal subtotal) =>
        new(customer, [new OrderLine("A", subtotal, 1)]);

    [Fact]
    public void Regular_customer_pays_the_subtotal() =>
        Assert.Equal(250m, PriceCalculator.Total(OrderOf(CustomerType.Regular)));

    [Fact]
    public void Loyal_customer_gets_five_percent_off() =>
        Assert.Equal(237.50m, PriceCalculator.Total(OrderOf(CustomerType.Loyal)));

    [Theory]
    [InlineData(CustomerType.Regular, 999.99, 999.99)]   // just below threshold: no extra discount
    [InlineData(CustomerType.Regular, 1000, 970.00)]     // 1000 - 3%
    [InlineData(CustomerType.Loyal, 1000, 921.50)]       // 1000 - 5% = 950, then - 3% = 921.50
    [InlineData(CustomerType.Loyal, 999.99, 949.9905)]   // loyal discount only
    public void Orders_of_1000_or_more_get_three_percent_off_after_customer_discount(
        CustomerType customer, decimal subtotal, decimal expected) =>
        Assert.Equal(expected, PriceCalculator.Total(OrderWithSubtotal(customer, subtotal)));
}

